SELECT count(DISTINCT customer_id) AS unique_customers
FROM sales
WHERE customer_id IS NOT NULL;

SELECT ROUND(AVG(order_revenue), 2) AS average_order_value
FROM (
    SELECT invoice, SUM(revenue) AS order_revenue
    FROM sales
    GROUP BY invoice
);

SELECT 
    ROUND(
        (COUNT(DISTINCT CASE WHEN is_cancelled THEN invoice END) * 100.0) / COUNT(DISTINCT invoice),
        2
    ) AS cancellation_percentage
FROM transactions;
